nested_innermost.source:
def outer():
    def inner():
        return 1
    return inner

class_body_attribute.source:
class Foo:
    x = 1
    def bar(self):
        return self.x

decorated_function.source:
def decorator(fn):
    return fn

@decorator
def foo():
    return 1

decorated_class.source:
def decorator(cls):
    return cls

@decorator
class Foo:
    def bar(self):
        return 1

addition_between_symbols.source:
def foo():
    return 1
def baz():
    return 3

deterministic_order.source:
def zzz():
    return 1

def aaa():
    return 2
